FONCTIONS_VALIDES = {
    "CHEF_EQUIPE",
    "OUVRIER_QUALIFIE",
    "OUVRIER",
    "MANOEUVRE",
    "CONDUCTEUR_ENGIN",
    "APPRENTI",
}


def migrer_chefs_et_nature(apps, schema_editor):
    EquipeChantier = apps.get_model("projets", "EquipeChantier")
    MembreEquipeChantier = apps.get_model("projets", "MembreEquipeChantier")

    # 1. Normaliser nature SOUS_TRAITANTE -> SOUS_TRAITANT
    EquipeChantier.objects.filter(nature="SOUS_TRAITANTE").update(nature="SOUS_TRAITANT")

    # 2. Normaliser les fonctions libres non valides en OUVRIER
    for membre in MembreEquipeChantier.objects.all():
        if membre.fonction not in FONCTIONS_VALIDES:
            membre.fonction = "OUVRIER"
            membre.save(update_fields=["fonction"])

    # 3. Créer un MembreEquipeChantier(fonction="CHEF_EQUIPE") pour chaque équipe
    # ayant chef_utilisateur ou chef_nom
    for equipe in EquipeChantier.objects.all():
        has_chef = (
            equipe.chef_utilisateur_id is not None
            or bool(equipe.chef_nom and equipe.chef_nom.strip())
        )
        if not has_chef:
            continue

        chef_existant = MembreEquipeChantier.objects.filter(
            equipe=equipe,
            fonction="CHEF_EQUIPE",
            supprime_le__isnull=True,
        ).exists()
        if not chef_existant:
            MembreEquipeChantier.objects.create(
                equipe=equipe,
                utilisateur=equipe.chef_utilisateur,
                nom=equipe.chef_nom or "",
                fonction="CHEF_EQUIPE",
                cree_par=equipe.cree_par,
            )


def reverser_chefs_et_nature(apps, schema_editor):
    EquipeChantier = apps.get_model("projets", "EquipeChantier")
    EquipeChantier.objects.filter(nature="SOUS_TRAITANT").update(nature="SOUS_TRAITANTE")


